/* the knobs: what the controls are, their values at generation, and the elements' laws (the deck's expressions) */
#define MKS_MNA_NKNOB 9
#define MKS_MNA_NKV   28            /* knob values: 0..5 the phase inverter's load, then one per pot section */
typedef struct { double VOL; double TREB; double BASS; double MID; double MASTER; double PRES; double LOWIN; double CAB; double ERA; } MksMnaKnobs;
static const MksMnaKnobs mks_mna_knobs_default = { 0.7, 0.5, 0.5, 0.5, 1.0, 0.0, 0.0, 1.0, 1.0 };
static const char* const mks_mna_knob_names[MKS_MNA_NKNOB] = { "VOL", "TREB", "BASS", "MID", "MASTER", "PRES", "LOWIN", "CAB", "ERA" };
#include "bn_preamp_ckt.h"   /* MK 81's pot laws and jack contacts (-I MK81/src/dsp) */
#define MKS_MK81_US 0   /* the edition: 1 = the export one, its 6550s (the device) */
#define MKS_MK81_US_POTS 0   /* its pots (0 only with MKS_MK81_US_POTS=0, to null the bench) */
#define MKS_MK81_NPAR 2.0   /* valves per side (the 50 W: one) */

/* the pot sections' values (val[6..]) for the knobs k; val[0..5] come from mks_pi_load.h (PRES) */
static inline void mks_mna_pot_values(const MksMnaKnobs* k, double* val)
{
    bn_preamp_ckt_pot_values(k->VOL, k->TREB, k->BASS, k->MID, k->MASTER, &val[6], MKS_MK81_US_POTS);   /* MK 81's laws */
    val[15] = 22e3 * (1.0 - k->PRES) + 1.0;                                    /* VR6 presence (power.py) */
    { const double* jv = k->LOWIN > 0.5 ? BN_PREAMP_CKT_JACK_LOW : BN_PREAMP_CKT_JACK_HIGH;
      for (int j = 0; j < BN_PREAMP_CKT_N_JACK; ++j) { val[16 + j] = jv[j]; } }
    {  /* MK81#4: the 4x12 load at Cabinet Feel k (power.py: Re 7.17, RP 34.3, f0 116.6, Q 6.52, LVC 0.000885; flat 8.0 ohm) */
        const double kc = !(k->CAB >= 0.0005) ? 0.0005 : (k->CAB > 1.0 ? 1.0 : k->CAB);
        const double rp = 34.3 * kc;
        val[20] = 8.0 + kc * (7.17 - 8.0);
        val[21] = rp;
        val[22] = 6.52 / (2.0 * 3.141592653589793 * 116.6 * rp);
        val[23] = 0.000885 * kc;
        val[24] = rp / (2.0 * 3.141592653589793 * 116.6 * 6.52);
        val[25] = 40.3 * kc;   /* MK81#159: the voice coil's loss scales with LVC */
    }
    val[26] = k->ERA > 0.5 ? 99.5 : 77.6;   /* MK81#195: rchg (bn_psu.h), the era's */
    val[27] = k->ERA > 0.5 ? 5e-05 : 0.0001;   /* MK81#195: C23, the era's */
}
